// ── Settings for this workflow ─────────────────────────────────────────────
// Google Sheet with the language tabs (the long ID in its URL)
const SPREADSHEET_ID = '11saBfyb7nnLA9OE5OCebVTGsCHQ2slrig6jbNJPxDrE';
// Renderer URL. On the VPS this is the docker service; locally set REEL_FACTORY_URL.
let renderer = 'http://reel-factory:3077';
try { renderer = $env.REEL_FACTORY_URL || renderer; } catch (e) { /* env access blocked */ }
// ───────────────────────────────────────────────────────────────────────────

// The webhook trigger can ask for one row: POST {"sheet": "German", "id": "DE-001"}
const body = $input.first().json.body ?? {};
return [{ json: { spreadsheetId: SPREADSHEET_ID, renderer, sheet: body.sheet ?? null, id: body.id ?? null } }];

// Keep the languages whose "Enabled" column is not FALSE/no/0; one item per language tab to read.
const off = new Set(['false', 'no', '0', 'off']);
const wanted = $('Config').first().json.sheet;
return $input.all().filter((item) => {
  const lang = item.json;
  if (!lang.Sheet) return false;
  if (wanted) return String(lang.Sheet).trim().toLowerCase() === String(wanted).trim().toLowerCase();
  return !off.has(String(lang.Enabled ?? '').trim().toLowerCase());
});

// Choose the row to render: the "ready" row with the earliest Publish date across all language tabs,
// or the row given by the webhook ({sheet, id}). Outputs nothing when there is no work.
const cfg = $('Config').first().json;

function parseDate(v) {
  if (v === null || v === undefined || v === '') return Infinity;
  if (typeof v === 'number') return Math.round((v - 25569) * 86400000); // Sheets serial date
  const t = Date.parse(String(v).trim().replace(' ', 'T'));
  return Number.isNaN(t) ? Infinity : t;
}

const rows = $input.all().map((item, i) => ({
  row: item.json,
  language: $('Enabled languages').itemMatching(i).json,
}));

let candidates;
if (cfg.id) {
  candidates = rows.filter((r) => String(r.row.ID).trim() === String(cfg.id).trim());
  candidates = candidates.filter((r) => String(r.row.Status).trim().toLowerCase() !== 'rendering');
} else {
  candidates = rows.filter((r) => String(r.row.Status ?? '').trim().toLowerCase() === 'ready');
}
if (!candidates.length) return [];

candidates.sort((a, b) => parseDate(a.row['Publish date']) - parseDate(b.row['Publish date']));
const { row, language } = candidates[0];

const brand = {};
for (const { json } of $('Read Brand').all()) {
  if (json.Key) brand[String(json.Key).trim()] = json.Value === undefined ? '' : String(json.Value).trim();
}

return [{ json: { sheet: language.Sheet, rowNumber: row.row_number, id: row.ID, row, language, brand, renderer: cfg.renderer } }];

// Turn the picked row into a reel-factory render request. Never throws: on a problem it returns
// { ok: false, error } so the row is marked "failed" with the reason.
const { sheet, row, language: lang, brand, renderer } = $input.first().json;
const s = (v) => (v === undefined || v === null ? '' : String(v).trim());

function deepMerge(a, b) {
  if (Array.isArray(b) || typeof b !== 'object' || b === null) return b;
  const out = { ...(a || {}) };
  for (const [k, v] of Object.entries(b)) out[k] = deepMerge(out[k], v);
  return out;
}
const slug = (v) => s(v).toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

// One builder per template: how the sheet columns become template data.
const builders = {
  'vocab-quiz': () => {
    const items = s(row.Vocabs)
      .split(/\r?\n/)
      .map((line) => line.trim())
      .filter(Boolean)
      .map((line) => {
        const [word, ipa, imageKey, imagePrompt] = line.split('|').map((p) => p.trim());
        const item = { word };
        if (ipa) item.ipa = ipa;
        if (imageKey) item.imageKey = imageKey;
        if (imagePrompt) item.imagePrompt = imagePrompt;
        return item;
      });
    if (!items.length) throw new Error('Vocabs is empty (one per line: word | IPA | image key)');
    const cta = {
      headline: s(lang['CTA headline']) || undefined,
      subheadline: s(lang['CTA subheadline']) || undefined,
      buttonText: s(lang['CTA button']) || undefined,
      footerText: s(lang['CTA footer']) || undefined,
      image: s(brand.ctaImage) || undefined,
    };
    return {
      title: s(row.Title) || s(lang['Question title']) || undefined,
      flag: s(lang.Flag).toLowerCase() || undefined,
      items,
      engagement: { enabled: true, text: s(lang['Comment prompt']) || undefined },
      cta,
    };
  },
};

try {
  const template = s(row.Template) || s(brand.defaultTemplate) || 'vocab-quiz';
  const build = builders[template];
  if (!build) throw new Error(`No sheet mapping for template "${template}" yet`);

  const name = s(row['Published name']) || s(row.ID);
  if (!name) throw new Error('Published name is empty');

  let request = {
    template,
    layout: s(row.Layout) || s(brand.defaultLayout) || undefined,
    brand: {
      name: s(brand.name) || undefined,
      website: s(brand.website) || undefined,
      logo: s(brand.logo) || undefined,
      primaryColor: s(brand.primaryColor) || undefined,
      accentColor: s(brand.accentColor) || undefined,
      wordmark: s(brand.wordmark) ? s(brand.wordmark).split(',').map((p) => p.trim()).filter(Boolean) : undefined,
    },
    voice: { provider: s(lang['Voice provider']) || undefined, voice: s(lang.Voice) || undefined },
    output: { quality: s(brand.quality) || 'standard', name: name.replace(/\s+/g, '-'), folder: s(lang['Video folder']) || slug(sheet) },
    data: build(),
    meta: { sheet, id: s(row.ID), rowNumber: row.row_number },
  };

  const options = s(row['Options (JSON)']);
  if (options) {
    let parsed;
    try {
      parsed = JSON.parse(options);
    } catch (e) {
      throw new Error(`Options (JSON) is not valid JSON: ${e.message}`);
    }
    request = deepMerge(request, parsed);
  }
  // Drop undefined values so the renderer's defaults apply
  request = JSON.parse(JSON.stringify(request));
  return [{ json: { ok: true, request, renderer } }];
} catch (e) {
  return [{ json: { ok: false, error: e.message, renderer } }];
}

// Row update right after picking: "rendering", or "failed" when the request could not be built.
const picked = $('Pick next row').first().json;
const built = $input.first().json;
return [{
  json: {
    row_number: picked.rowNumber,
    Status: built.ok ? 'rendering' : 'failed',
    Error: built.ok ? '' : built.error,
    'Video URL': '',
    'Thumbnail URL': '',
    'Duration (s)': '',
    'Images generated': '',
    'Rendered at': '',
    'Job ID': '',
  },
}];

// Row update with the render result. Input is either the renderer's callback (Wait node: body = job)
// or the HTTP response when the renderer refused the request (statusCode 4xx/5xx).
const picked = $('Pick next row').first().json;
const input = $input.first().json;
let job;
if (input.statusCode === 202) {
  job = { status: 'failed', id: input.body?.id, error: 'Timed out waiting for the renderer (no callback within 30 min)' };
} else if (input.statusCode !== undefined) {
  job = { status: 'failed', error: input.body?.error || `Renderer answered HTTP ${input.statusCode}` };
} else {
  job = input.body ?? input;
}
const done = job.status === 'done';
const generated = job.images?.generated ?? [];
return [{
  json: {
    row_number: picked.rowNumber,
    Status: done ? 'rendered' : 'failed',
    'Video URL': done ? job.videoUrl : '',
    'Thumbnail URL': done ? job.thumbnailUrl : '',
    'Duration (s)': done ? Math.round(job.duration * 10) / 10 : '',
    'Images generated': generated.join(', '),
    'Rendered at': done ? new Date(job.finishedAt || Date.now()).toISOString().replace('T', ' ').slice(0, 16) : '',
    'Job ID': job.id || '',
    Error: done ? '' : String(job.error || job.status || 'unknown error').slice(0, 500),
  },
}];

// Mark the execution as failed (so n8n error workflows / notifications fire) after the row was updated.
let result = null;
try {
  result = $('Result fields').first().json;
} catch (e) {
  // "Result fields" did not run: the request could not be built (row already marked failed)
}
if (!result) {
  throw new Error(`Could not build the render request: ${$('Build render request').first().json.error}`);
}
if (result.Status !== 'rendered') throw new Error(`Render failed for row ${result.row_number}: ${result.Error}`);
return [{ json: { ...$('Pick next row').first().json, result } }];
